import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { ComCodeType } from '~/entities/comcode/model/constants';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';
import { BACK_BLOCKED_PATHS, PATHS } from '~/shared/routes/paths';
import { ComCodeResponseDTO } from './dtos';

export const getCodeManage = (id: ComCodeType) => () => {
  return resultify(axios.get<ComCodeResponseDTO>(`${API_URLS.codeManage(id)}`));
};

export const useGetCodeManage = (id: ComCodeType, options?: QueryOptions<ComCodeResponseDTO, CBDCAxiosError>) => {
  const token = useStore.getState().authSlice.jwt;
  const { pathname } = window.location;
  const isReady = !!token && ![...BACK_BLOCKED_PATHS[PATHS.home]].includes(pathname);

  return useQuery<ComCodeResponseDTO, CBDCAxiosError>({
    queryKey: queries.comCode.codeManage({ id }).queryKey,
    queryFn: getCodeManage(id),
    staleTime: 1000 * 60 * 60 * 24, // 하루동안 공통 코드는 캐시로 처리
    gcTime: Infinity,
    ...options,
    select: (data) => {
      if (data?.tbSysCodeValueList && data?.tbSysCodeValueList?.length > 0) {
        const hash = Object.fromEntries(data.tbSysCodeValueList.map((item) => [item.cdValue, item]));
        data = { ...data, hash: hash };
      }
      return data;
    },
    enabled: isReady,
  });
};
